begin;
create table if not exists public.mme_gl_accounts(account_id uuid primary key default gen_random_uuid(),account_code text not null unique,account_name text not null,account_type text not null check(account_type in ('asset','liability','equity','revenue','expense')),normal_balance text not null check(normal_balance in ('debit','credit')),parent_account_id uuid references public.mme_gl_accounts(account_id),is_control_account boolean not null default false,active boolean not null default true,description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_gl_periods(period_id uuid primary key default gen_random_uuid(),period_name text not null unique,start_date date not null,end_date date not null,period_status text not null default 'open' check(period_status in ('open','closed','locked')),closed_by_auth_user_id uuid,closed_at timestamptz,created_at timestamptz not null default now(),check(end_date>=start_date));
create table if not exists public.mme_gl_journal_entries(entry_id uuid primary key default gen_random_uuid(),entry_number text not null unique,period_id uuid not null references public.mme_gl_periods(period_id),entry_date date not null,description text not null,source_module text not null default 'manual',source_reference text,entry_status text not null default 'posted' check(entry_status in ('posted','reversed')),debit_total numeric(16,2) not null check(debit_total>0),credit_total numeric(16,2) not null check(credit_total>0),created_by_auth_user_id uuid not null,posted_at timestamptz not null default now(),reversal_of_entry_id uuid references public.mme_gl_journal_entries(entry_id),created_at timestamptz not null default now(),unique(source_module,source_reference),check(debit_total=credit_total));
create table if not exists public.mme_gl_journal_lines(line_id uuid primary key default gen_random_uuid(),entry_id uuid not null references public.mme_gl_journal_entries(entry_id) on delete restrict,account_id uuid not null references public.mme_gl_accounts(account_id),line_number integer not null check(line_number>0),description text,debit numeric(16,2) not null default 0 check(debit>=0),credit numeric(16,2) not null default 0 check(credit>=0),created_at timestamptz not null default now(),unique(entry_id,line_number),check((debit>0 and credit=0) or (credit>0 and debit=0)));
create table if not exists public.mme_gl_audit_events(event_id uuid primary key default gen_random_uuid(),actor_auth_user_id uuid not null,action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}',request_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_gl_lines_account_idx on public.mme_gl_journal_lines(account_id,entry_id);
create index if not exists mme_gl_entries_period_idx on public.mme_gl_journal_entries(period_id,entry_date);
create index if not exists mme_gl_period_dates_idx on public.mme_gl_periods(start_date,end_date,period_status);
insert into public.mme_gl_accounts(account_code,account_name,account_type,normal_balance,is_control_account,description) values
('1000','Cash and Cash Equivalents','asset','debit',true,'Cash and bank balances'),
('1100','Accounts Receivable','asset','debit',true,'Customer receivables control account'),
('1200','Inventory','asset','debit',true,'Inventory asset control account'),
('1500','Property and Equipment','asset','debit',false,'Fixed assets'),
('2000','Accounts Payable','liability','credit',true,'Vendor payables control account'),
('2100','Sales Tax Payable','liability','credit',true,'Sales tax liability'),
('2200','Payroll Liabilities','liability','credit',true,'Payroll deductions and liabilities'),
('3000','Owner Equity','equity','credit',false,'Owner capital and equity'),
('3100','Retained Earnings','equity','credit',false,'Accumulated retained earnings'),
('4000','Product Sales Revenue','revenue','credit',false,'Retail product sales'),
('4100','Subscription Revenue','revenue','credit',false,'Subscription platform revenue'),
('4200','Other Operating Revenue','revenue','credit',false,'Other operating revenue'),
('5000','Cost of Goods Sold','expense','debit',false,'Cost of goods sold'),
('6000','Payroll Expense','expense','debit',false,'Wages and commissions'),
('6100','Rent and Occupancy','expense','debit',false,'Rent and occupancy costs'),
('6200','Marketing Expense','expense','debit',false,'Advertising and marketing'),
('6300','Operating Expenses','expense','debit',false,'General operating expenses')
on conflict(account_code) do nothing;
create or replace function public.mme_gl_post_journal(p_entry_number text,p_entry_date date,p_description text,p_source_module text,p_source_reference text,p_actor uuid,p_lines jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_period public.mme_gl_periods%rowtype;v_entry uuid;v_debits numeric(16,2);v_credits numeric(16,2);v_count integer;v_line jsonb;v_account uuid;v_debit numeric(16,2);v_credit numeric(16,2);v_n integer:=0;begin if p_entry_number is null or length(trim(p_entry_number))=0 or p_description is null or length(trim(p_description))=0 then raise exception 'journal_header_required';end if;if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)<2 or jsonb_array_length(p_lines)>200 then raise exception 'invalid_journal_lines';end if;select * into v_period from public.mme_gl_periods where p_entry_date between start_date and end_date and period_status='open' for update;if not found then raise exception 'no_open_accounting_period';end if;select count(*),coalesce(sum((x->>'debit')::numeric),0),coalesce(sum((x->>'credit')::numeric),0) into v_count,v_debits,v_credits from jsonb_array_elements(p_lines) x;if v_count<2 or v_debits<=0 or v_credits<=0 or round(v_debits,2)<>round(v_credits,2) then raise exception 'journal_not_balanced';end if;insert into public.mme_gl_journal_entries(entry_number,period_id,entry_date,description,source_module,source_reference,debit_total,credit_total,created_by_auth_user_id) values(p_entry_number,v_period.period_id,p_entry_date,p_description,coalesce(nullif(p_source_module,''),'manual'),p_source_reference,v_debits,v_credits,p_actor) returning entry_id into v_entry;for v_line in select * from jsonb_array_elements(p_lines) loop v_n:=v_n+1;v_account:=(v_line->>'account_id')::uuid;v_debit:=coalesce((v_line->>'debit')::numeric,0);v_credit:=coalesce((v_line->>'credit')::numeric,0);if v_debit<0 or v_credit<0 or ((v_debit>0)=(v_credit>0)) then raise exception 'invalid_journal_line';end if;if not exists(select 1 from public.mme_gl_accounts where account_id=v_account and active) then raise exception 'inactive_or_unknown_gl_account';end if;insert into public.mme_gl_journal_lines(entry_id,account_id,line_number,description,debit,credit) values(v_entry,v_account,v_n,nullif(v_line->>'description',''),v_debit,v_credit);end loop;insert into public.mme_gl_audit_events(actor_auth_user_id,action,entity_type,entity_id,details,request_id) values(p_actor,'journal_posted','journal_entry',v_entry,jsonb_build_object('entry_number',p_entry_number,'debit_total',v_debits,'credit_total',v_credits),gen_random_uuid());return v_entry;end $$;
create or replace function public.mme_gl_close_period(p_period_id uuid,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v public.mme_gl_periods%rowtype;begin select * into v from public.mme_gl_periods where period_id=p_period_id for update;if not found then raise exception 'period_not_found';end if;if v.period_status<>'open' then raise exception 'period_not_open';end if;update public.mme_gl_periods set period_status='closed',closed_by_auth_user_id=p_actor,closed_at=now() where period_id=p_period_id;insert into public.mme_gl_audit_events(actor_auth_user_id,action,entity_type,entity_id,details,request_id) values(p_actor,'period_closed','accounting_period',p_period_id,'{}',gen_random_uuid());return p_period_id;end $$;
create or replace view public.mme_gl_trial_balance as select a.account_id,a.account_code,a.account_name,a.account_type,coalesce(sum(l.debit),0)::numeric(16,2) as debit_total,coalesce(sum(l.credit),0)::numeric(16,2) as credit_total,coalesce(sum(l.debit-l.credit),0)::numeric(16,2) as net_debit_balance from public.mme_gl_accounts a left join public.mme_gl_journal_lines l on l.account_id=a.account_id left join public.mme_gl_journal_entries e on e.entry_id=l.entry_id and e.entry_status='posted' group by a.account_id,a.account_code,a.account_name,a.account_type;
create or replace view public.mme_gl_income_statement as select a.account_id,a.account_code,a.account_name,a.account_type,coalesce(sum(l.credit-l.debit),0)::numeric(16,2) as net_amount from public.mme_gl_accounts a left join public.mme_gl_journal_lines l on l.account_id=a.account_id left join public.mme_gl_journal_entries e on e.entry_id=l.entry_id and e.entry_status='posted' where a.account_type in ('revenue','expense') group by a.account_id,a.account_code,a.account_name,a.account_type;
create or replace view public.mme_gl_balance_sheet as select a.account_id,a.account_code,a.account_name,a.account_type,coalesce(sum(case when a.normal_balance='debit' then l.debit-l.credit else l.credit-l.debit end),0)::numeric(16,2) as balance from public.mme_gl_accounts a left join public.mme_gl_journal_lines l on l.account_id=a.account_id left join public.mme_gl_journal_entries e on e.entry_id=l.entry_id and e.entry_status='posted' where a.account_type in ('asset','liability','equity') group by a.account_id,a.account_code,a.account_name,a.account_type,a.normal_balance;
alter table public.mme_gl_accounts enable row level security;alter table public.mme_gl_periods enable row level security;alter table public.mme_gl_journal_entries enable row level security;alter table public.mme_gl_journal_lines enable row level security;alter table public.mme_gl_audit_events enable row level security;
revoke all on public.mme_gl_accounts,public.mme_gl_periods,public.mme_gl_journal_entries,public.mme_gl_journal_lines,public.mme_gl_audit_events from public,anon,authenticated;
grant all on public.mme_gl_accounts,public.mme_gl_periods,public.mme_gl_journal_entries,public.mme_gl_journal_lines,public.mme_gl_audit_events to service_role;
revoke all on public.mme_gl_trial_balance,public.mme_gl_income_statement,public.mme_gl_balance_sheet from public,anon,authenticated;
grant select on public.mme_gl_trial_balance,public.mme_gl_income_statement,public.mme_gl_balance_sheet to service_role;
revoke all on function public.mme_gl_post_journal(text,date,text,text,text,uuid,jsonb) from public,anon,authenticated;
revoke all on function public.mme_gl_close_period(uuid,uuid) from public,anon,authenticated;
grant execute on function public.mme_gl_post_journal(text,date,text,text,text,uuid,jsonb) to service_role;
grant execute on function public.mme_gl_close_period(uuid,uuid) to service_role;
commit;